import { useState, useEffect } from 'react';
import { Icon } from '@iconify/react';
import api from '../utils/api';
import toast from 'react-hot-toast';

export default function Admin() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingBook, setEditingBook] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    author: '',
    description: '',
    category: 'Aqeedah',
    level: 'Beginner',
    language: 'English',
    pages: '',
    publisher: '',
    publishYear: '',
    tags: '',
    featured: false
  });
  const [file, setFile] = useState(null);
  const [cover, setCover] = useState(null);

  const categories = ['Aqeedah', 'Hadith', 'Tafsir', 'Fiqh', 'Seerah', 'Tazkiyah', 'Arabic', 'History', 'Self-Help', 'Spirituality', 'Other'];
  const levels = ['Beginner', 'Intermediate', 'Advanced', 'Contemporary'];

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      const { data } = await api.get('/books');
      setBooks(data);
    } catch (error) {
      toast.error('Failed to fetch books');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const form = new FormData();
    Object.keys(formData).forEach(key => {
      form.append(key, formData[key]);
    });
    if (file) form.append('file', file);
    if (cover) form.append('cover', cover);

    try {
      if (editingBook) {
        await api.put(`/books/${editingBook._id}`, form, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        toast.success('Book updated successfully');
      } else {
        await api.post('/books', form, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        toast.success('Book added successfully');
      }
      resetForm();
      fetchBooks();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to save book');
    }
  };

  const handleEdit = (book) => {
    setEditingBook(book);
    setFormData({
      title: book.title,
      author: book.author,
      description: book.description,
      category: book.category,
      level: book.level,
      language: book.language,
      pages: book.pages || '',
      publisher: book.publisher || '',
      publishYear: book.publishYear || '',
      tags: book.tags?.join(', ') || '',
      featured: book.featured
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this book?')) {
      try {
        await api.delete(`/books/${id}`);
        toast.success('Book deleted');
        fetchBooks();
      } catch (error) {
        toast.error('Failed to delete book');
      }
    }
  };

  const resetForm = () => {
    setFormData({
      title: '',
      author: '',
      description: '',
      category: 'Aqeedah',
      level: 'Beginner',
      language: 'English',
      pages: '',
      publisher: '',
      publishYear: '',
      tags: '',
      featured: false
    });
    setFile(null);
    setCover(null);
    setEditingBook(null);
    setShowForm(false);
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold text-green-700 dark:text-green-400">Admin Dashboard</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">Manage your Islamic book collection</p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-xl font-semibold inline-flex items-center gap-2 transition-all"
        >
          <Icon icon={showForm ? 'ph:x-duotone' : 'ph:plus-duotone'} className="w-5 h-5" />
          {showForm ? 'Cancel' : 'Add New Book'}
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
        {[
          { label: 'Total Books', value: books.length, icon: 'ph:books-duotone' },
          { label: 'Categories', value: [...new Set(books.map(b => b.category))].length, icon: 'ph:folders-duotone' },
          { label: 'Total Downloads', value: books.reduce((sum, b) => sum + (b.downloads || 0), 0), icon: 'ph:download-duotone' },
          { label: 'Total Views', value: books.reduce((sum, b) => sum + (b.views || 0), 0), icon: 'ph:eye-duotone' },
        ].map(stat => (
          <div key={stat.label} className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow text-center">
            <Icon icon={stat.icon} className="w-8 h-8 mx-auto text-green-600 mb-2" />
            <div className="text-2xl font-bold text-green-700 dark:text-green-400">{stat.value}</div>
            <div className="text-sm text-gray-500 dark:text-gray-400">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Add/Edit Form */}
      {showForm && (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6 mb-8">
          <h2 className="text-xl font-bold mb-6 text-green-700 dark:text-green-400">
            {editingBook ? 'Edit Book' : 'Add New Book'}
          </h2>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Title *</label>
              <input type="text" required value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Author *</label>
              <input type="text" required value={formData.author} onChange={e => setFormData({...formData, author: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium mb-1">Description *</label>
              <textarea required rows="3" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Category</label>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600">
                {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Level</label>
              <select value={formData.level} onChange={e => setFormData({...formData, level: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600">
                {levels.map(l => <option key={l} value={l}>{l}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Language</label>
              <input type="text" value={formData.language} onChange={e => setFormData({...formData, language: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Pages</label>
              <input type="number" value={formData.pages} onChange={e => setFormData({...formData, pages: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Publisher</label>
              <input type="text" value={formData.publisher} onChange={e => setFormData({...formData, publisher: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Publish Year</label>
              <input type="number" value={formData.publishYear} onChange={e => setFormData({...formData, publishYear: e.target.value})}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Tags (comma separated)</label>
              <input type="text" value={formData.tags} onChange={e => setFormData({...formData, tags: e.target.value})}
                placeholder="e.g., Islam, Quran, Beginner"
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Book File (PDF/EPUB)</label>
              <input type="file" onChange={e => setFile(e.target.files[0])}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Cover Image</label>
              <input type="file" accept="image/*" onChange={e => setCover(e.target.files[0])}
                className="w-full px-4 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" />
            </div>
            <div className="flex items-center gap-2">
              <input type="checkbox" id="featured" checked={formData.featured} 
                onChange={e => setFormData({...formData, featured: e.target.checked})}
                className="w-4 h-4" />
              <label htmlFor="featured" className="text-sm font-medium">Featured Book</label>
            </div>
            <div className="md:col-span-2 flex gap-3">
              <button type="submit" className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-semibold">
                {editingBook ? 'Update Book' : 'Add Book'}
              </button>
              <button type="button" onClick={resetForm} className="bg-gray-300 hover:bg-gray-400 dark:bg-gray-600 px-6 py-2 rounded-lg font-semibold">
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Books List */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg overflow-hidden">
        <div className="p-6 border-b dark:border-gray-700">
          <h2 className="text-xl font-bold text-green-700 dark:text-green-400">All Books</h2>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 dark:bg-gray-700">
              <tr>
                <th className="text-left p-4 text-sm font-semibold">Title</th>
                <th className="text-left p-4 text-sm font-semibold hidden md:table-cell">Author</th>
                <th className="text-left p-4 text-sm font-semibold hidden md:table-cell">Category</th>
                <th className="text-left p-4 text-sm font-semibold hidden md:table-cell">Level</th>
                <th className="text-left p-4 text-sm font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-gray-700">
              {books.map(book => (
                <tr key={book._id} className="hover:bg-gray-50 dark:hover:bg-gray-750">
                  <td className="p-4">
                    <div className="font-medium">{book.title}</div>
                    <div className="text-xs text-gray-500 md:hidden">{book.author}</div>
                  </td>
                  <td className="p-4 hidden md:table-cell text-gray-600 dark:text-gray-400">{book.author}</td>
                  <td className="p-4 hidden md:table-cell">
                    <span className="px-2 py-1 rounded-full text-xs bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300">
                      {book.category}
                    </span>
                  </td>
                  <td className="p-4 hidden md:table-cell">
                    <span className="px-2 py-1 rounded-full text-xs bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300">
                      {book.level}
                    </span>
                  </td>
                  <td className="p-4">
                    <div className="flex gap-2">
                      <button onClick={() => handleEdit(book)} className="p-2 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900 text-blue-600">
                        <Icon icon="ph:pencil-duotone" className="w-5 h-5" />
                      </button>
                      <button onClick={() => handleDelete(book._id)} className="p-2 rounded-lg hover:bg-red-100 dark:hover:bg-red-900 text-red-600">
                        <Icon icon="ph:trash-duotone" className="w-5 h-5" />
                      </button>
                      {book.fileUrl && (
                        <a href={`http://localhost:5000/api/books/${book._id}/download`} 
                           className="p-2 rounded-lg hover:bg-green-100 dark:hover:bg-green-900 text-green-600">
                          <Icon icon="ph:download-duotone" className="w-5 h-5" />
                        </a>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
